//! Real private local OpenDAL backend. Keys are generated by the service, never
//! caller paths. Files are write-once; do not enable Fs.atomic_write_dir, whose
//! rename is not a conditional immutable publication operation.
use super::*;
#[cfg(unix)]
use std::os::unix::fs::{MetadataExt, OpenOptionsExt, PermissionsExt};
use std::{
    fs::{self, File, OpenOptions},
    path::{Path, PathBuf},
};
pub(super) struct LocalObjects {
    pub root_id: String,
    root: PathBuf,
    identity: (u64, u64),
    pub op: opendal::Operator,
    _lock: Option<File>,
    writable: bool,
}
impl LocalObjects {
    pub fn open(root: &Path) -> Result<Self, ArtifactError> {
        #[cfg(not(unix))]
        {
            let _ = root;
            return Err(ArtifactError::StoragePolicy);
        }
        #[cfg(unix)]
        {
            let meta = fs::symlink_metadata(root)?;
            if !meta.is_dir() || meta.file_type().is_symlink() || meta.mode() & 0o077 != 0 {
                return Err(ArtifactError::StoragePolicy);
            }
            let root = root.canonicalize()?;
            let identity = (meta.dev(), meta.ino());
            let lock = private_file(&root.join(".store-lock"), false)?;
            lock.try_lock().map_err(|_| ArtifactError::Busy)?;
            let root_id = match private_file(&root.join(".store-id"), true) {
                Ok(mut f) => {
                    use std::io::Write;
                    let id = uuid::Uuid::new_v4().to_string();
                    f.write_all(id.as_bytes())?;
                    f.sync_all()?;
                    File::open(&root)?.sync_all()?;
                    id
                }
                Err(ArtifactError::Io(e)) if e.kind() == std::io::ErrorKind::AlreadyExists => {
                    use std::io::Read;
                    let mut s = String::new();
                    private_file(&root.join(".store-id"), false)?
                        .take(129)
                        .read_to_string(&mut s)?;
                    if uuid::Uuid::parse_str(&s).is_err() {
                        return Err(ArtifactError::StoragePolicy);
                    }
                    s
                }
                Err(e) => return Err(e),
            };
            let op = opendal::Operator::new(
                opendal::services::Fs::default()
                    .root(root.to_str().ok_or(ArtifactError::StoragePolicy)?),
            )?;
            if !op.info().capability().write_with_if_not_exists {
                return Err(ArtifactError::StoragePolicy);
            }
            Ok(Self {
                root_id,
                root,
                identity,
                op,
                _lock: Some(lock),
                writable: true,
            })
        }
    }
    pub fn open_read_only(root: &Path) -> Result<Self, ArtifactError> {
        #[cfg(not(unix))]
        {
            let _ = root;
            return Err(ArtifactError::StoragePolicy);
        }
        #[cfg(unix)]
        {
            use std::io::Read;
            let m = fs::symlink_metadata(root)?;
            if !m.is_dir() || m.file_type().is_symlink() || m.mode() & 0o077 != 0 {
                return Err(ArtifactError::StoragePolicy);
            }
            let root = root.canonicalize()?;
            let f = OpenOptions::new()
                .read(true)
                .custom_flags(libc::O_NOFOLLOW | libc::O_NONBLOCK)
                .open(root.join(".store-id"))?;
            let fm = f.metadata()?;
            if !fm.is_file() || fm.nlink() != 1 || fm.mode() & 0o077 != 0 {
                return Err(ArtifactError::StoragePolicy);
            }
            let mut root_id = String::new();
            f.take(129).read_to_string(&mut root_id)?;
            uuid::Uuid::parse_str(&root_id).map_err(|_| ArtifactError::StoragePolicy)?;
            let op = opendal::Operator::new(
                opendal::services::Fs::default()
                    .root(root.to_str().ok_or(ArtifactError::StoragePolicy)?),
            )?;
            Ok(Self {
                root_id,
                root,
                identity: (m.dev(), m.ino()),
                op,
                _lock: None,
                writable: false,
            })
        }
    }
    pub fn check_root(&self) -> Result<(), ArtifactError> {
        #[cfg(unix)]
        {
            let m = fs::symlink_metadata(&self.root)?;
            if !m.is_dir()
                || m.file_type().is_symlink()
                || m.mode() & 0o077 != 0
                || (m.dev(), m.ino()) != self.identity
            {
                return Err(ArtifactError::StoragePolicy);
            }
        }
        Ok(())
    }
    pub fn check_file(&self, key: &str) -> Result<(), ArtifactError> {
        self.check_root()?;
        key_valid(key)?;
        let m = fs::symlink_metadata(self.root.join(key))?;
        if !m.is_file() || m.file_type().is_symlink() {
            return Err(ArtifactError::StoragePolicy);
        }
        #[cfg(unix)]
        if m.nlink() != 1 || m.mode() & 0o077 != 0 {
            return Err(ArtifactError::StoragePolicy);
        }
        Ok(())
    }
    pub async fn writer(&self, key: &str) -> Result<opendal::Writer, ArtifactError> {
        if !self.writable {
            return Err(ArtifactError::StoragePolicy);
        }
        self.check_root()?;
        key_valid(key)?;
        Ok(self.op.writer_with(key).if_not_exists(true).await?)
    }
    pub fn finish_write(&self, key: &str) -> Result<(), ArtifactError> {
        self.check_root()?;
        key_valid(key)?;
        // OpenDAL's writer is lazy: the file exists only after write/close.
        // The private root protects staging bytes until this seal completes.
        #[cfg(unix)]
        {
            let f = OpenOptions::new()
                .read(true)
                .custom_flags(libc::O_NOFOLLOW | libc::O_NONBLOCK)
                .open(self.root.join(key))?;
            let m = f.metadata()?;
            if !m.is_file() || m.nlink() != 1 {
                return Err(ArtifactError::StoragePolicy);
            }
            f.set_permissions(fs::Permissions::from_mode(0o600))?;
            f.sync_all()?;
        }
        self.check_file(key)?;
        self.sync()?;
        Ok(())
    }
    pub async fn read(&self, key: &str, size: u64) -> Result<opendal::Buffer, ArtifactError> {
        self.check_file(key)?;
        if self.op.stat(key).await?.content_length() != size {
            return Err(ArtifactError::Integrity);
        }
        let data = if size == 0 {
            opendal::Buffer::from(Vec::<u8>::new())
        } else {
            self.op.read_with(key).range(0..size).await?
        };
        self.check_file(key)?;
        if data.len() as u64 != size {
            return Err(ArtifactError::Integrity);
        }
        Ok(data)
    }
    pub async fn verified_audio_chunk(
        &self,
        key: &str,
        size: u64,
        start: u64,
        expected: &str,
    ) -> Result<Vec<u8>, ArtifactError> {
        use orange_protocol::pricing::AUDIO_INPUT_CHUNK_BYTES;
        if size > orange_protocol::artifacts::MEDIA_LIMIT
            || start >= size
            || !start.is_multiple_of(AUDIO_INPUT_CHUNK_BYTES as u64)
        {
            return Err(ArtifactError::Invalid);
        }
        self.check_file(key)?;
        if self.op.stat(key).await?.content_length() != size {
            return Err(ArtifactError::Integrity);
        }
        let end = (start + AUDIO_INPUT_CHUNK_BYTES as u64).min(size);
        let data = self.op.read_with(key).range(start..end).await?.to_vec();
        self.check_file(key)?;
        if data.len() as u64 != end - start || hex::encode(Sha256::digest(&data)) != expected {
            return Err(ArtifactError::Integrity);
        }
        Ok(data)
    }
    pub async fn remove(&self, key: &str) -> Result<(), ArtifactError> {
        if !self.writable {
            return Err(ArtifactError::StoragePolicy);
        }
        self.check_root()?;
        key_valid(key)?;
        let metadata = match fs::symlink_metadata(self.root.join(key)) {
            Ok(m) => m,
            Err(e) if e.kind() == std::io::ErrorKind::NotFound => return Ok(()),
            Err(e) => return Err(e.into()),
        };
        // A failed lazy writer may not have reached permission sealing. The
        // private root and generated immutable key still identify its orphan.
        if !metadata.is_file() || metadata.file_type().is_symlink() {
            return Err(ArtifactError::StoragePolicy);
        }
        #[cfg(unix)]
        if metadata.nlink() != 1 {
            return Err(ArtifactError::StoragePolicy);
        }
        self.op.delete(key).await?;
        self.sync()?;
        Ok(())
    }
    pub fn sync(&self) -> Result<(), ArtifactError> {
        self.check_root()?;
        File::open(&self.root)?.sync_all()?;
        Ok(())
    }
}
pub(super) fn key_valid(key: &str) -> Result<(), ArtifactError> {
    let id = key
        .strip_prefix("staging-")
        .or_else(|| key.strip_prefix("published-"))
        .or_else(|| key.strip_prefix("quarantine-"))
        .ok_or(ArtifactError::StoragePolicy)?;
    uuid::Uuid::parse_str(id).map_err(|_| ArtifactError::StoragePolicy)?;
    Ok(())
}
#[cfg(unix)]
fn private_file(path: &Path, new: bool) -> Result<File, ArtifactError> {
    let mut options = OpenOptions::new();
    options
        .read(true)
        .write(true)
        .mode(0o600)
        .custom_flags(libc::O_NOFOLLOW | libc::O_NONBLOCK);
    if new {
        options.create_new(true);
    } else {
        options.create(true).truncate(false);
    }
    let f = options.open(path)?;
    let m = f.metadata()?;
    if !m.is_file() || m.nlink() != 1 || m.mode() & 0o077 != 0 {
        return Err(ArtifactError::StoragePolicy);
    }
    Ok(f)
}
